const $=s=>document.querySelector(s);let sounds=[],category='すべて',current=null,player=new Audio(),favorites;try{favorites=new Set(JSON.parse(localStorage.getItem('favorites')||'[]'))}catch{favorites=new Set()}const status=t=>$('#status').textContent=t;
function filtered(){return sounds.filter(s=>(category==='すべて'||category==='★ お気に入り'&&favorites.has(s.id)||s.category===category)&&(s.title+' '+s.original).toLowerCase().includes($('#search').value.toLowerCase()))}
function render(){const list=filtered();$('#count').textContent=`${list.length} VOICES / ${sounds.length} TOTAL`;$('#grid').replaceChildren(...list.map(s=>{const card=document.createElement('article');card.className='card'+(current===s.id?' playing':'');const star=document.createElement('button');star.className='star';star.textContent=favorites.has(s.id)?'★':'☆';star.setAttribute('aria-label',s.title+'をお気に入り切替');star.onclick=()=>{favorites.has(s.id)?favorites.delete(s.id):favorites.add(s.id);try{localStorage.setItem('favorites',JSON.stringify([...favorites]))}catch{status('お気に入りを保存できませんでした')}render()};const b=document.createElement('button');b.className='play';const tag=document.createElement('span');tag.className='tag';tag.textContent='▶ '+s.category;const title=document.createElement('b');title.textContent=s.title;b.append(tag,title);b.onclick=()=>play(s);card.append(star,b);return card}));if(!list.length)$('#grid').textContent='該当する音声がありません。'}
async function play(s){player.pause();current=s.id;player.src=s.src;$('#now').textContent=s.title;render();try{await player.play();navigator.vibrate?.(15)}catch{status('再生できません。通信状態を確認して再度タップしてください。');current=null;render()}}
$('#stop').onclick=()=>{player.pause();player.currentTime=0;current=null;$('#now').textContent='停止しました';render()};player.onended=()=>{current=null;$('#now').textContent='声を選んでタップ';render()};$('#volume').oninput=e=>player.volume=Number(e.target.value);$('#search').oninput=render;$('#random').onclick=()=>{const list=filtered();if(list.length)play(list[Math.floor(Math.random()*list.length)])};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{await installPrompt?.prompt();$('#install').hidden=true};
$('#offline').onclick=async()=>{const button=$('#offline');button.disabled=true;try{await navigator.serviceWorker.ready;const cache=await caches.open('anya-audio-v1');let n=0;for(const s of sounds){const req=new Request(s.src);if(!await cache.match(req)){const res=await fetch(req);if(!res.ok)throw Error();await cache.put(req,res)}status(`音声を保存中 ${++n} / ${sounds.length}`)}status(`全${sounds.length}音声を保存しました。オフラインで再生できます。`)}catch{status('保存できませんでした。HTTPSと空き容量・通信を確認して再試行してください。')}finally{button.disabled=false}};
fetch('sounds.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{sounds=data;for(const c of ['すべて','★ お気に入り',...new Set(sounds.map(s=>s.category))]){const b=document.createElement('button');b.textContent=c;b.className=c===category?'active':'';b.onclick=()=>{category=c;$('#categories').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()};$('#categories').append(b)}render();status('全90音声 • タップですぐに再生')}).catch(()=>status('一覧を読み込めません。再読み込みしてください。'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>status('オフライン機能にはHTTPS接続が必要です。'));
